/**
 * 실물 재현 대조의 **알려진 차이** — 모델이 원문과 일부러 다르게 내는 자리 (QA/인수기준 「알려진 차이」 · 한 몸).
 *
 * 대조기(`src/domain/assembly/compare.ts`)를 조용히 완화하지 않는다 — 대신 원문 줄(파싱양식)에 이 목록을 적용해 **기대 줄**을 만들고,
 * 조립 결과를 그 기대 줄과 글자 그대로 대조한다. 목록에 없는 차이는 전부 불일치다.
 * 쓰는 곳: `real.test.ts`(시드 → 조립) · 화면 E2E(`tests/e2e/real/_lib/compare.ts` · `tests/e2e/_lib/terms.ts`).
 */

import { ALPHA2607, ALPHA2610, REVISED_IN_2610, type SpecialSpec } from "../../../scripts/terms/config";

export interface KnownDifference {
  /** 상품 픽스처 폴더 — 알파Plus 는 뿌리 「」, 메리츠 「메리츠」, 알파Plus2607 「알파2607」. */
  dir: string;
  file: string;
  /** 조 헤딩 줄(파싱양식 `## 제N조(조 명)`)의 조 명. */
  article: string;
  /** 이 줄(그 조 안, 공백 무시로 비교) 뒤에 `lines` 를 넣는다 — `replace` 면 이 줄을 `lines` 로 바꾼다. */
  after: string;
  lines: string[];
  /** 기준 줄을 바꾼다(표준화로 달라지는 표기) — 없으면 뒤에 넣는다(원문 누락). */
  replace?: true;
  /** 바꾸기 범위 — 기준 줄 앞 · 뒤로 몇 줄까지 함께 바꾸나 [앞, 뒤] (박스 · 표 블록이 통째로 다른 자리). 없으면 기준 줄 하나. */
  span?: [number, number];
  /** 줄 안 글 바꾸기 — 그 조의 모든 줄에서 `after`(글 조각)를 `lines[0]` 으로 바꾼다(조 참조의 조 명 표기 · 항 표지처럼 같은 조각이 여러 줄에 나오는 자리). */
  within?: true;
  /**
   * 파일 전체 글 바꾸기 — 그 파일의 모든 줄(조 헤딩 포함)에서 `after`(글 조각)를 `lines[0]` 으로 바꾼다. `article` 은 쓰지 않는다(「*」).
   * 조 명 자체가 다른 자리(조 헤딩 + 그 조를 가리키는 조 참조 라벨이 어느 조 · 어느 파일에든 있다). 조 단위 차이(옛 조 명으로 찾는다)를 모두 얹은 뒤에 바꾼다.
   */
  everywhere?: true;
  /**
   * 판 대조 — 이 조는 공용 템플릿 「보통약관(일반)」의 판(바탕 알파Plus2607) 글로 찍힌다(상품 조 사본을 두지 않은 판 표기 차이 — 박스 나눔 ·
   * 띄어쓰기 · 원문 오탈자, 2026-10-28). 그 판 원문(`edition` = 상품 픽스처 폴더)의 같은 조 기대 줄(그 판의 알려진 차이를 얹은 것)로 조 본문을 바꾼다.
   * 조 헤딩은 제 원문 번호 그대로(대조는 조 번호를 보지 않는다). `after` · `lines` 는 쓰지 않는다. 조 단위 차이 중 가장 먼저 얹는다.
   * `article` 이 「*」 이면 **파일 판 대조** — 파일째 그 판의 기대 줄이다(담보 템플릿이 다른 판 원문으로 만들어진 특약, 알파Plus2607 ↔ 2610). 다른 차이는 얹지 않는다.
   */
  edition?: string;
  /** 파일 판 대조(「*」 + edition) 위에 얹는 글 바꾸기 — `everywhere` 와 함께. 그 판 기대 줄을 이 상품 문맥으로 고친다(상해안심2610 위치 호칭 등). */
  onEdition?: true;
  /** 파일 판 대조에서 그 판의 파일 이름이 다를 때(상해안심 「갱신형_X」 ↔ 알파 「X」 — 갱신형으로 탑재한 비갱신 담보). */
  editionFile?: string;
  /** 인수기준의 차이 이름 — 사람이 읽는다. */
  why: string;
}

/** 알파Plus2607 — 2604 와 함께 쓰는 템플릿 · 함수조항 · 박스가 2604 원문의 표기로 찍히는 자리 (상품군 공통화, QA/실물재현/알파플러스2607_모델명세 §5). */
const A7 = "알파2607";

/** 원문(2607) 한 줄이 함께 쓰는 2604 것에서 여러 줄로 찍힌다 — 2604 원문 추출의 줄 넘김이 박스 줄 · 호에 남았다. */
const split = (file: string, article: string, joined: string, lines: string[]): KnownDifference => ({
  dir: A7,
  file,
  article,
  after: joined,
  lines,
  replace: true,
  why: "함께 쓰는 2604 템플릿 · 함수조항 · 박스의 줄 나눔 — 2607 원문은 한 줄(PDF 추출 차이)",
});

/** 2607 원문의 그림 + 【용어풀이】 블록이 함께 쓰는 2604 템플릿에서 예시 표로 찍힌다(같은 예시의 다른 표기). */
const span = (file: string, article: string, anchor: string, range: [number, number], lines: string[]): KnownDifference => ({
  dir: A7,
  file,
  article,
  after: anchor,
  lines,
  replace: true,
  span: range,
  why: "함께 쓰는 2604 템플릿의 예시 표 — 2607 원문은 그림 + 【용어풀이】 설명(같은 예시의 다른 표기)",
});

/** 2607 원문이 박스 둘로 나눈 자리를 2604 템플릿은 박스 하나로 둔다 — 둘째 박스 머리(```` ``` ```` · ```` ```용어풀이 ````)가 없다. */
const merged = (file: string, article: string, secondTitle: string): KnownDifference => ({
  dir: A7,
  file,
  article,
  after: secondTitle,
  lines: [secondTitle],
  replace: true,
  span: [2, 0],
  why: "함께 쓰는 2604 템플릿의 박스 하나 — 2607 원문은 같은 글을 박스 둘로 나눴다",
});

