/**
 * 알파 형제 — 알파Plus2610 과 같은 구성의 상품(케어프리 M-Basket2610). 담보 · 템플릿 · 보통약관 설정을 그대로 쓰므로 파일째 알파Plus2610 기대 줄과 대조한다.
 * 원문이 알파Plus2610 원문과 같다(상품명만 다름 — real.test 가 확인). 자동갱신 특약 본문의 상품명은 템플릿에 박혀 알파Plus2610 이름으로 찍힌다.
 */
export const ALPHA_SIBLINGS: readonly { dir: string; name: string }[] = [{ dir: "케어프리2610", name: "무배당 케어프리보험 M-Basket2610" }];
const SIBLING_DIFFERENCES = (files: (dir: string) => readonly string[]): KnownDifference[] =>
  ALPHA_SIBLINGS.flatMap((sib) =>
    files(sib.dir).map((file) => ({
      dir: sib.dir,
      file,
      article: "*",
      after: "",
      lines: [],
      edition: A10,
      why:
        file === "자동갱신.md"
          ? "알파Plus2610 담보 그대로 — 자동갱신 특약 본문의 상품명(「무배당 알파Plus보장보험2610 특별약관 중」)이 템플릿에 박혀 있다"
          : "알파Plus2610 과 같은 구성 — 담보 · 템플릿 · 보통약관을 그대로 쓴다(원문이 같다)",
    })),
  );
/** 형제 상품 폴더의 fixture 목록 — 시드 쪽(브라우저 E2E 포함)에서 fs 를 쓰지 않도록 알파Plus2610 탑재 목록에서 짓는다. */
const siblingFiles = (): readonly string[] => ["보통약관.md", ...SHARED_2607_IN_2610, ...ALPHA2610_DIFFERENCES.filter((d) => d.dir === A10 && d.article === "*" && d.edition === A7).map((d) => d.file), ...REVISED_FILES, ...ALPHA2610.specials.flatMap((s) => [s.file!, ...(s.auto?.renewal ? [s.auto.renewal] : [])])];

export const KNOWN_DIFFERENCES: readonly KnownDifference[] = [
  ...BASE_DIFFERENCES,
  ...ALPHA2610_DIFFERENCES,
  ...SA2610_DIFFERENCES,
  ...BRAIN2610_DIFFERENCES,
  ...SIBLING_DIFFERENCES(() => [...new Set(siblingFiles())]),
];

const squash = (s: string) => s.replace(/\s+/g, "");

/** 조 단위 차이(줄 안 · 줄 바꾸기 · 넣기)를 기대 줄에 얹는다. */
function applyArticleDifferences(out: string[], list: readonly KnownDifference[]): void {
  for (const d of list) {
    const { heading, end } = articleSpan(out, d.article);
    if (heading < 0) throw new Error(`알려진 차이 「${d.why}」: 조 「${d.article}」 없음`);
    if (d.within) {
      let hits = 0;
      for (let i = heading + 1; i < end; i++) {
        if (!out[i].includes(d.after)) continue;
        out[i] = out[i].split(d.after).join(d.lines[0]);
        hits++;
      }
      if (hits === 0) throw new Error(`알려진 차이 「${d.why}」: 조 「${d.article}」 안에 「${d.after}」가 없다`);
      continue;
    }
    const at = out.findIndex((l, i) => i > heading && i < end && squash(l) === squash(d.after));
    if (at < 0) throw new Error(`알려진 차이 「${d.why}」: 조 「${d.article}」 안에 기준 줄이 없다`);
    const [before, after] = d.span ?? [0, 0];
    if (at - before <= heading || at + after >= end) throw new Error(`알려진 차이 「${d.why}」: 바꾸기 범위가 조 「${d.article}」 밖으로 넘친다`);
    if (d.replace) out.splice(at - before, before + 1 + after, ...d.lines);
    else out.splice(at + 1, 0, ...d.lines);
  }
}

/** 조 헤딩 줄 자리와 그 조의 끝(다음 헤딩) — 없으면 heading = -1. */
function articleSpan(lines: readonly string[], article: string): { heading: number; end: number } {
  const heading = lines.findIndex((l) => /^##\s/.test(l) && squash(l).endsWith(`(${squash(article)})`));
  const next = lines.findIndex((l, i) => i > heading && /^##?\s/.test(l));
  return { heading, end: next < 0 ? lines.length : next };
}

/**
 * 원문 줄 → 기대 줄 — 그 파일의 알려진 차이를 적용한다. 자리를 못 찾으면 던진다(목록이 원문과 어긋난 것).
 * 판 대조(`edition`)는 그 판 원문 줄이 있어야 한다 — `read(dir, file)` 로 받는다(파일 읽기는 호출자 몫).
 */
export function expectedLines(dir: string, file: string, source: readonly string[], list: readonly KnownDifference[] = KNOWN_DIFFERENCES, read?: (dir: string, file: string) => readonly string[]): string[] {
  const mine = list.filter((x) => x.dir === dir && x.file === file);
  // 파일 판 대조 — 담보 템플릿이 다른 판 원문으로 만들어진 특약(알파Plus2607 ↔ 2610)은 파일째 그 판의 기대 줄이다
  const whole = mine.find((x) => x.edition !== undefined && x.article === "*");
  if (whole) {
    if (!read) throw new Error(`알려진 차이 「${whole.why}」: 판 대조(${whole.edition})는 그 판 원문을 읽을 read 가 있어야 한다`);
    const theirs = whole.editionFile ?? file;
    const out = expectedLines(whole.edition!, theirs, read(whole.edition!, theirs), list, read);
    // 그 판 글 위에 이 상품 문맥에서 달라지는 글 바꾸기(everywhere)만 얹는다 — 위치 호칭 · 납입면제 없는 상품의 준용예외(상해안심2610)
    applyArticleDifferences(out, mine.filter((x) => x.onEdition && !x.everywhere));
    for (const d of mine.filter((x) => x.everywhere && x.onEdition)) {
      const before = out.join("\n");
      for (let i = 0; i < out.length; i++) out[i] = out[i].split(d.after).join(d.lines[0]);
      if (out.join("\n") === before) throw new Error(`알려진 차이 「${d.why}」: 파일 「${file}」(${whole.edition}) 안에 「${d.after}」가 없다`);
    }
    return out;
  }
  const out = [...source];
  const editions = new Map<string, string[]>();
  for (const d of mine.filter((x) => x.edition !== undefined)) {
    const edition = d.edition!;
    if (!read) throw new Error(`알려진 차이 「${d.why}」: 판 대조(${edition})는 그 판 원문을 읽을 read 가 있어야 한다`);
    if (!editions.has(edition)) editions.set(edition, expectedLines(edition, file, read(edition, file), list, read));
    const theirs = editions.get(edition)!;
    const own = articleSpan(out, d.article);
    const other = articleSpan(theirs, d.article);
    if (own.heading < 0 || other.heading < 0) throw new Error(`알려진 차이 「${d.why}」: 조 「${d.article}」 없음(${own.heading < 0 ? dir || "알파Plus" : edition})`);
    out.splice(own.heading + 1, own.end - own.heading - 1, ...theirs.slice(other.heading + 1, other.end));
  }
  applyArticleDifferences(out, mine.filter((x) => !x.everywhere && x.edition === undefined));
  for (const d of mine.filter((x) => x.everywhere)) {
    let hits = 0;
    for (let i = 0; i < out.length; i++) {
      if (!out[i].includes(d.after)) continue;
      out[i] = out[i].split(d.after).join(d.lines[0]);
      hits++;
    }
    if (hits === 0) throw new Error(`알려진 차이 「${d.why}」: 파일 「${file}」 안에 「${d.after}」가 없다`);
  }
  return out;
}
